-- ============================================
-- LUMA — Thème 8 : MOYEN 2/3 x4 — Négocier avec une créature magique
-- ============================================


update scenarios set content = '{"characters": {"gryphon": "le griffon"}, "start_node": "n1", "nodes": {"n1": {"speaker": "gryphon", "text": "(A massive gryphon blocks the narrow bridge.) None shall pass without proving their worth!", "text_fr": "(Un griffon massif bloque le pont étroit.) Nul ne passera sans prouver sa valeur !", "choices": [{"text": "I mean you no harm, noble gryphon. May we speak first?", "text_fr": "Je ne vous veux aucun mal, noble griffon. Pouvons-nous parler d''abord ?", "next": "n2"}, {"text": "What proof of worth do you require of me?", "text_fr": "Quelle preuve de valeur exigez-vous de moi ?", "next": "n2b"}]}, "n2": {"speaker": "gryphon", "text": "Speak, then, traveler. Few dare address me so calmly.", "text_fr": "Parle, alors, voyageur. Peu osent s''adresser à moi si calmement.", "choices": [{"text": "I seek only safe passage, not conflict with a creature as majestic as you.", "text_fr": "Je cherche seulement un passage sûr, pas de conflit avec une créature aussi majestueuse que vous.", "next": "n3"}]}, "n2b": {"speaker": "gryphon", "text": "Answer this: what walks on four legs at dawn, two at noon, and three at dusk?", "text_fr": "Réponds à ceci : qu''est-ce qui marche à quatre pattes à l''aube, deux à midi, et trois au crépuscule ?", "choices": [{"text": "A human — crawling as a babe, walking as an adult, using a cane in old age.", "text_fr": "Un humain — rampant en tant que bébé, marchant adulte, utilisant une canne dans sa vieillesse.", "next": "n3"}]}, "n3": {"speaker": "gryphon", "text": "(Impressed, ruffling feathers) You speak with wisdom, or answer with cleverness. Rare, indeed.", "text_fr": "(Impressionné, ébouriffant ses plumes) Vous parlez avec sagesse, ou répondez avec ingéniosité. Rare, en effet.", "choices": [{"text": "I''ve traveled far and learned much along the way.", "text_fr": "J''ai voyagé loin et beaucoup appris en chemin.", "next": "n4"}, {"text": "I simply try to think before I act, noble one.", "text_fr": "J''essaie simplement de réfléchir avant d''agir, noble créature.", "next": "n4"}]}, "n4": {"speaker": "gryphon", "text": "Tell me, why do you seek to cross this bridge? What drives you?", "text_fr": "Dites-moi, pourquoi cherchez-vous à traverser ce pont ? Qu''est-ce qui vous motive ?", "choices": [{"text": "I seek an ancient artifact that could restore balance to these lands.", "text_fr": "Je cherche un artefact ancien qui pourrait rétablir l''équilibre dans ces terres.", "next": "n5"}, {"text": "My village suffers, and only what lies beyond can save it.", "text_fr": "Mon village souffre, et seul ce qui se trouve au-delà peut le sauver.", "next": "n5"}]}, "n5": {"speaker": "gryphon", "text": "A noble cause, if true. But many have lied to me before with similar tales.", "text_fr": "Une noble cause, si c''est vrai. Mais beaucoup m''ont menti auparavant avec des histoires similaires.", "choices": [{"text": "I understand your caution. What can I offer to prove my sincerity?", "text_fr": "Je comprends votre prudence. Que puis-je offrir pour prouver ma sincérité ?", "next": "n6"}, {"text": "I have no way to prove it but my word — and my word is true.", "text_fr": "Je n''ai aucun moyen de le prouver, seulement ma parole — et ma parole est vraie.", "next": "n6b"}]}, "n6": {"speaker": "gryphon", "text": "Bring me a feather from the phoenix that nests atop the eastern cliffs, and I shall trust you.", "text_fr": "Apportez-moi une plume du phénix qui niche au sommet des falaises orientales, et je vous ferai confiance.", "choices": [{"text": "That''s a difficult task, but I accept the challenge.", "text_fr": "C''est une tâche difficile, mais j''accepte le défi.", "next": "n7"}, {"text": "Is there perhaps another way to earn your trust, one less perilous?", "text_fr": "Y a-t-il peut-être un autre moyen de gagner votre confiance, moins périlleux ?", "next": "n7b"}]}, "n6b": {"speaker": "gryphon", "text": "(Studies you intently, golden eyes unblinking.) Your eyes do not waver. That, at least, is telling.", "text_fr": "(Vous étudie intensément, yeux dorés sans ciller.) Vos yeux ne vacillent pas. Cela, au moins, en dit long.", "choices": [{"text": "I have nothing to hide from you, gryphon.", "text_fr": "Je n''ai rien à cacher de vous, griffon.", "next": "n7"}]}, "n7": {"speaker": "gryphon", "text": "(After a long pause) Very well. I shall trust the sincerity I sense in you.", "text_fr": "(Après une longue pause) Très bien. Je vais faire confiance à la sincérité que je sens en vous.", "choices": [{"text": "Thank you, noble gryphon. I won''t forget this kindness.", "text_fr": "Merci, noble griffon. Je n''oublierai pas cette gentillesse.", "next": "n8"}]}, "n7b": {"speaker": "gryphon", "text": "(Considers) Perhaps... if you can answer one more riddle correctly, I shall let you pass.", "text_fr": "(Réfléchit) Peut-être... si vous répondez correctement à une autre énigme, je vous laisserai passer.", "choices": [{"text": "I accept — ask your riddle.", "text_fr": "J''accepte — posez votre énigme.", "next": "n8"}]}, "n8": {"speaker": "gryphon", "text": "Step aside, and let the bridge be yours to cross, traveler of true heart.", "text_fr": "Écartez-vous, et que le pont soit à vous pour traverser, voyageur au cœur sincère.", "choices": [{"text": "I''m deeply grateful, gryphon. Farewell, and may we meet again.", "text_fr": "Je vous suis profondément reconnaissant, griffon. Adieu, et puissions-nous nous revoir.", "next": "end_passed"}]}, "end_passed": {"speaker": "gryphon", "text": "Go now, and may fortune guide your path, brave one.", "text_fr": "Allez maintenant, et que la fortune guide votre chemin, brave voyageur.", "end": true, "ending_label": "Passage obtenu par la diplomatie, sans combat 🦅🤝"}}}'::jsonb, is_playable = true
where title = 'Négocier avec une créature magique'
  and theme_id = (select id from scenario_themes where position = 8 and language_id = (select id from languages where code = 'en'));
